"""Explicit source-read annotations for the first native-source proposals."""
import json,re
from second_canada_author import OUT,source,pages_for,dump

def para(pages,page,n):
    t=pages[page-1];m=re.search(r'(?m)^\s*'+str(n)+r'\.\s*$',t)
    if not m:
        # Explicitly requested continuation of a source-read paragraph on this page.
        following=re.search(r'(?m)^\s*'+str(n+1)+r'\.\s*$',t)
        if not following:
            assert not re.search(r'(?m)^\s*\d{1,3}\.\s*$',t),(page,n)
            return t.strip()
        return t[:following.start()].strip()
    tail=t[m.end():]; nxt=re.search(r'(?m)^\s*\d{1,3}\.\s*$',tail)
    return tail[:nxt.start() if nxt else len(tail)].strip()
def ref(pages,page,n): return dict(page=page,paragraph=n,quote=para(pages,page,n))
def event(pages,page,n,date,description,labels=(),precision=None):
    return dict(page=page,paragraph=n,date=date,event=description,labels=list(labels),quote=para(pages,page,n),date_precision=precision or ('day' if date and len(date)==10 else 'month' if date and len(date)==7 else 'year' if date else 'unknown'))

